(function(){let e=self;e.onmessage=async t=>{let n;try{let r=new Blob([t.data.source],{type:t.data.mimeType});n=await createImageBitmap(r);let i=new OffscreenCanvas(n.width,n.height),a=i.getContext(`2d`,{alpha:!0});if(!a)throw Error(`2D canvas unavailable`);a.drawImage(n,0,0);let o=await i.convertToBlob({type:`image/webp`,quality:t.data.quality});e.postMessage({blob:o})}catch(t){let n=t instanceof Error?t.message:`browser image compression failed`;e.postMessage({error:n})}finally{n?.close()}}})();